param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'readonly-span-indexed-access-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult}}
$rows=[Collections.Generic.List[object]]::new();$op=[Reflection.Emit.OpCodes];$nativeCalls=0
foreach($kind in @('Char','Byte')){$element=[type]::GetType('System.'+$kind,$true);$arrayType=$element.MakeArrayType();$span=if($kind -eq 'Char'){[type]'System.ReadOnlySpan[char]'}else{[type]'System.ReadOnlySpan[byte]'};$bridge=[Reflection.Emit.DynamicMethod]::new('ReadIndex'+$kind,[object],[type[]]@([Array],[int],[int],[int]));$il=$bridge.GetILGenerator();$local=$il.DeclareLocal($span);$il.Emit($op::Ldarg_0);$il.Emit($op::Castclass,$arrayType);$il.Emit($op::Ldarg_1);$il.Emit($op::Ldarg_2);$il.Emit($op::Newobj,$span.GetConstructor([type[]]@($arrayType,[int],[int])));$il.Emit($op::Stloc_0);$il.Emit($op::Ldloca_S,$local);$il.Emit($op::Ldarg_3);$il.Emit($op::Call,$span.GetProperty('Item').GetMethod);$il.Emit($op::Ldobj,$element);$il.Emit($op::Box,$element);$il.Emit($op::Ret);$read=$bridge.CreateDelegate([Func[Array,int,int,int,object]])
 foreach($view in $plan.views){$offset=[int]$view[0];$length=[int]$view[1];$indices=@(-1,0,1,($length-1),$length,[int]::MaxValue)|Sort-Object -Unique;foreach($index in $indices){foreach($mode in $plan.mutationModes){$newValues=@(0);if($mode -ne 'none'){$newValues=$plan.writeValues.PSObject.Properties[$kind].Value};foreach($newValue in $newValues){$seed=[int[]]$plan.seeds.PSObject.Properties[$kind].Value;if($kind -eq 'Char'){$values=[char[]]$seed;$value=[char][int]$newValue}else{$values=[byte[]]$seed;$value=[byte]$newValue};$calls=0;try{$calls++;$before=[int]$read.Invoke($values,$offset,$length,$index);if($mode -ne 'none'){$position=$offset+$index;if($mode -eq 'other'){$position=($position+1)%$values.Length};$values[$position]=$value};$calls++;$after=[int]$read.Invoke($values,$offset,$length,$index);$result=[ordered]@{ok=$true;values=[int[]]@($before,$after)}}catch{$result=Failure $_};$nativeCalls+=$calls;$rows.Add([ordered]@{kind=$kind;offset=$offset;length=$length;index=$index;mode=$mode;newValue=[int]$newValue;calls=$calls;result=$result;buffer=[int[]]$values})}}}}
}
if($rows.Count -ne $plan.expectedRows){throw 'Incomplete readonly index matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';nativeCalls=$nativeCalls;rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS readonly span indexed access: $($rows.Count) rows and $nativeCalls native reads"
